#!/usr/bin/env bash
# Bake plan 'islands': Iceland (16 land chunks at z7) and Reunion (14 land chunks at z11), 1024 px + 128 px margin,
# so each painting is native at chunk zoom + 2. Styles: every argus-atlas preset (antique, tolkien, imhof, watercolor,
# cyberpunk, minecraft, pixel). 30 chunks x 7 styles = 210 jobs. Recipes other than antique are antique.json with
# the name and preset swapped, as bakeplan does, plus "z_factor": "auto" and "vertical_exaggeration": 1:
# hillshade and slope are scaled by 1/cos(centre latitude), so Mercator does not flatten Iceland's relief.
# argus-atlas 0.3.0 refuses neighbours with another relief, so these style dirs hold 0.3.0 chunks only.
# One painting per chunk serves the base view (chunk zoom) and the zoom-in (chunk zoom + 2): coarser tiles are
# downsampled from it, so zoom levels cannot drift apart. All-sea chunks are skipped, as for cook-strait.sh.
# Host paths come from the environment, e.g. ATLAS_HOST=<dir with dem/ and recipes/> ATLAS_MAPS=<maps share>
# ATLAS_MODELS=<model tree holding the checkpoint>. Needs ComfyUI answering on 127.0.0.1:8188.
set -euo pipefail
: "${ATLAS_HOST:?}" "${ATLAS_MAPS:?}" "${ATLAS_MODELS:?}"
IMAGE=ghcr.io/smk762/argus-atlas:0.3.0
RUN="docker run --rm -u $(id -u):$(id -g) -w /tmp --add-host host.docker.internal:host-gateway -e COMFYUI_BASE_URL=http://host.docker.internal:8188 -e ATLAS_ALLOW_BAKE=1 -e ATLAS_RECIPES_DIR=/data/recipes -e ATLAS_MODELS_DIR=/data/models -e ATLAS_JOBS_DIR=/data/out/atlas -v $ATLAS_HOST/dem:/data/dem -v $ATLAS_HOST/recipes:/data/recipes:ro -v $ATLAS_MODELS:/data/models:ro -v $ATLAS_MAPS:/data/out/atlas $IMAGE"

# --- iceland: DEM, OSM, chunks ---
[ -f "$ATLAS_HOST/dem/iceland_glo30.tif" ] || $RUN argus-atlas dem --bbox -25.6741,62.7447,-10.8884,67.7528 --out /data/dem/iceland_glo30.tif --allow-missing --max-tiles 120
[ -f "$ATLAS_HOST/dem/osm/iceland/osm.json" ] || $RUN argus-atlas osm --bbox -25.6641,62.7547,-10.8984,67.7428 --zoom 9 --layers water,rivers,roads,forest,urban,glaciers --out /data/dem/osm/iceland
curl -sf -m 5 http://127.0.0.1:8188/system_stats >/dev/null || { echo "ComfyUI is not answering on :8188"; exit 1; }
mkdir -p "$ATLAS_MAPS/areas/iceland/antique"
[ -f "$ATLAS_MAPS/areas/iceland/antique/antique-7-57-31/fantasy.pmtiles" ] || $RUN argus-atlas chunk --tile 7/57/31 --recipe antique --dem /data/dem/iceland_glo30.tif --size 1024 --margin 128 --sea-level 0 --layer water=/data/dem/osm/iceland/water.geojson --layer rivers=/data/dem/osm/iceland/rivers.geojson --layer roads=/data/dem/osm/iceland/roads.geojson --layer forest=/data/dem/osm/iceland/forest.geojson --layer urban=/data/dem/osm/iceland/urban.geojson --layer glaciers=/data/dem/osm/iceland/glaciers.geojson --out /data/out/atlas/areas/iceland/antique/antique-7-57-31
[ -f "$ATLAS_MAPS/areas/iceland/antique/antique-7-58-31/fantasy.pmtiles" ] || $RUN argus-atlas chunk --tile 7/58/31 --recipe antique --dem /data/dem/iceland_glo30.tif --size 1024 --margin 128 --sea-level 0 --layer water=/data/dem/osm/iceland/water.geojson --layer rivers=/data/dem/osm/iceland/rivers.geojson --layer roads=/data/dem/osm/iceland/roads.geojson --layer forest=/data/dem/osm/iceland/forest.geojson --layer urban=/data/dem/osm/iceland/urban.geojson --layer glaciers=/data/dem/osm/iceland/glaciers.geojson --out /data/out/atlas/areas/iceland/antique/antique-7-58-31
[ -f "$ATLAS_MAPS/areas/iceland/antique/antique-7-55-32/fantasy.pmtiles" ] || $RUN argus-atlas chunk --tile 7/55/32 --recipe antique --dem /data/dem/iceland_glo30.tif --size 1024 --margin 128 --sea-level 0 --layer water=/data/dem/osm/iceland/water.geojson --layer rivers=/data/dem/osm/iceland/rivers.geojson --layer roads=/data/dem/osm/iceland/roads.geojson --layer forest=/data/dem/osm/iceland/forest.geojson --layer urban=/data/dem/osm/iceland/urban.geojson --layer glaciers=/data/dem/osm/iceland/glaciers.geojson --out /data/out/atlas/areas/iceland/antique/antique-7-55-32
